from nafes_ext_pipeline import attach_bank_ids_and_validate_lessons


def _c(title_en, title_ar, body_en, body_ar, f_en, cap_ar, f_ar, svg):
    return nafes_concept(title_en, title_ar, body_en, body_ar, f_en, cap_ar, f_ar, svg, svg)


def _ex(ex_id, t_en, t_ar, passage, ask_en, ask_ar, pairs, idea_en, s_en, c_en, idea_ar, s_ar, c_ar, svg):
    box = wrap_passage_box(passage) if passage else ""
    q_en = f"Walkthrough: {ask_en}" if not box else f"Read the walkthrough card.{box}{ask_en}"
    q_ar = f"تطبيق محلول: {ask_ar}" if not box else f"اقرأ المثال المحلول:{box}{ask_ar}"
    return ext_worked_example(
        ex_id, t_en, t_ar, q_en, q_ar, idea_en, s_en, c_en, idea_ar, s_ar, c_ar,
        diagram_en=svg, diagram_ar=svg, bilingual_pairs=pairs,
    )


