def main() -> None:
    lessons = build_english_lessons()
    assert len(lessons) == 18
    attach_bank_ids_and_validate_lessons(
        lessons,
        bank_path=ROOT / "data" / "nafes_english.json",
        bp_key="nafes_english_blueprint",
        out_path=ROOT / "data" / "nafes_english_lessons.json",
    )


if __name__ == "__main__":
    main()
